import type { SecondFactorDefinition } from '@cms/sdk/plugin';
import type { RecoveryCodeRepository } from '#api/domain/auth/recovery-service';
import type { TokenIssuer } from '#api/domain/auth/ports';

/** Codes are generated by the existing recent-interactive-session recovery endpoint. */
export const createRecoveryFactor = (
  codes: RecoveryCodeRepository,
  tokens: TokenIssuer,
): SecondFactorDefinition => ({
  label: 'Recovery code',
  enrolled: async (user) => (await codes.status(user.id)).remaining > 0,
  challenge: () => ({
    kind: 'fields',
    fields: [
      {
        name: 'code',
        label: 'Recovery code',
        type: 'code',
        required: true,
        autocomplete: 'one-time-code',
      },
    ],
  }),
  verify: (user, step) =>
    codes.consume(
      user.id,
      tokens.digest(
        (step.values.code ?? '').trim().replaceAll('-', '').toUpperCase(),
      ),
    ),
});
